"use strict";
// An island package shaped like a service's HTTP helpers: a
// client that requests over HTTP and answers promises, a base class that
// native code extends, and work that allocates enough to collect garbage.
const http = require("node:http");

function get(port, path) {
  return new Promise((resolve, reject) => {
    http
      .get({ host: "127.0.0.1", port, path, agent: false }, (res) => {
        let body = "";
        res.setEncoding("utf8");
        res.on("data", (chunk) => (body += chunk));
        res.on("end", () => resolve({ status: res.statusCode, body }));
      })
      .on("error", reject);
  });
}

function delay(ms, value) {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

// Allocates and drops a few megabytes, so collections run while native
// callers are on the stack.
function churn(seed) {
  let keep = 0;
  for (let i = 0; i < 2000; i++) {
    const a = new Array(64).fill(seed + i);
    keep += a.length + JSON.stringify({ i, a: a.slice(0, 4) }).length;
  }
  return keep;
}

// Recursion deep enough to use tens of kilobytes of the stack it runs on.
function depth(n) {
  const pad = [n, n + 1, n + 2, n + 3];
  return n <= 0 ? pad.length : depth(n - 1) + (pad[n % 4] > 0 ? 1 : 0);
}

class Handler {
  constructor(name) {
    this.name = name;
    this.count = 0;
  }
  async handle(path) {
    this.count++;
    await delay(1);
    return `${this.name}:${path}`;
  }
}

module.exports = { get, delay, churn, depth, Handler };
